      >
        <Plus aria-hidden className="size-4" />
        {actionLabel}
      </button>
    </motion.section>
  )
}

"use client"

/** Clean-room AE dashboard piece. Theme tokens only. */

import { useId, useState, type FormEvent } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Plus, X } from "lucide-react"

import { AeCard, AeEmpty } from "@/components/ui/ae/card-shell"

export type QuickNote = { id: string; text: string }

export type QuickNotesCardProps = {
  title?: string
  notes?: QuickNote[]
  onChange?: (notes: QuickNote[]) => void
  placeholder?: string
  className?: string
}

export function QuickNotesCard({ title = "Notas rápidas", notes: initial = [], onChange, placeholder = "Escribe una nota…", className }: QuickNotesCardProps) {
  const reduce = !!useReducedMotion()
  const inputId = useId()
  const [notes, setNotes] = useState(initial)
  const [draft, setDraft] = useState("")
  const commit = (next: QuickNote[]) => {
    setNotes(next)
    onChange?.(next)
  }
  const add = (event: FormEvent) => {
    event.preventDefault()
    const text = draft.trim()
    if (!text) return
    commit([...notes, { id: `${Date.now()}`, text }])
    setDraft("")
  }
  return (
    <AeCard title={title} className={className}>
      {notes.length === 0 ? <AeEmpty>Sin notas por ahora.</AeEmpty> : null}
      <ul className="grid gap-2">
        <AnimatePresence initial={false}>
          {notes.map((note) => (
            <motion.li
              key={note.id}
              layout={!reduce}
              initial={reduce ? false : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduce ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, x: 12 }}
              className="group flex min-w-0 items-start gap-2 rounded-2xl bg-muted/60 px-3 py-2 text-sm"
            >
              <span aria-hidden className="mt-1.5 size-1.5 shrink-0 rounded-full bg-primary" />
              <span className="min-w-0 flex-1 break-words">{note.text}</span>
              <button
                type="button"
                aria-label={`Borrar nota: ${note.text}`}
                onClick={() => commit(notes.filter((item) => item.id !== note.id))}
                className="grid size-6 shrink-0 place-items-center rounded-full text-muted-foreground outline-none hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
              >
                <X aria-hidden className="size-3.5" />
              </button>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
      <form onSubmit={add} className="flex items-center gap-2">
        <label htmlFor={inputId} className="sr-only">
          Nueva nota
        </label>
        <input
          id={inputId}
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder={placeholder}
          className="h-10 min-w-0 flex-1 rounded-full border border-input bg-background px-4 text-sm outline-none placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring"
        />
        <button type="submit" aria-label="Agregar nota" disabled={!draft.trim()} className="grid size-10 shrink-0 place-items-center rounded-full bg-foreground text-background outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:opacity-40">
          <Plus aria-hidden className="size-4" />
        </button>
      </form>
    </AeCard>
  )
}

"use client"

/** Clean-room AE dashboard piece. A ranked "map-ish" list of clients per state. Theme tokens only. */

import { motion, useReducedMotion } from "motion/react"
import { MapPin } from "lucide-react"

import { growTransition } from "@/lib/ae-dash"
import { AeCard, AeEmpty } from "@/components/ui/ae/card-shell"

export type StateDistributionCardProps = { title?: string; items: { label: string; value: number }[]; unit?: string; className?: string }

export function StateDistributionCard({ title = "Clientes por estado", items, unit = "clientes", className }: StateDistributionCardProps) {
  const reduce = !!useReducedMotion()
  const max = Math.max(1, ...items.map((item) => item.value))
  const total = items.reduce((sum, item) => sum + item.value, 0)
  return (
    <AeCard title={title} className={className} action={<span className="text-xs text-muted-foreground tabular-nums">{total.toLocaleString("es-MX")} {unit}</span>}>
      {items.length === 0 ? (
        <AeEmpty>Aún no hay clientes con estado.</AeEmpty>
      ) : (
        <ol className="grid gap-3">
          {items.map((item, index) => (
            <li key={item.label} className="grid min-w-0 gap-1.5">
              <div className="flex min-w-0 items-center gap-2 text-sm">
                <MapPin aria-hidden className={index === 0 ? "size-4 shrink-0 text-primary" : "size-4 shrink-0 text-muted-foreground"} />
                <span className="min-w-0 flex-1 truncate">{item.label}</span>
                <span className="font-semibold tabular-nums">{item.value.toLocaleString("es-MX")}</span>
              </div>
              <div className="h-2 overflow-hidden rounded-full bg-muted" aria-hidden>
                <motion.div className={index === 0 ? "h-full rounded-full bg-primary" : "h-full rounded-full bg-foreground/70"} style={{ originX: 0 }} initial={{ scaleX: reduce ? item.value / max : 0 }} animate={{ scaleX: item.value / max }} transition={growTransition(reduce, index)} />
              </div>
            </li>
          ))}
        </ol>
      )}
    </AeCard>
  )
}

"use client"

/** Clean-room AE dashboard piece. Bars grow from the bottom; the last bar uses the accent. Theme tokens only. */

import { useId, useState } from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { growTransition } from "@/lib/ae-dash"
import { AeCard, AeEmpty, AeSkeleton } from "@/components/ui/ae/card-shell"

export type BarPoint = { label: string; value: number }

export type BarTrendCardProps = {
  title?: string
  data: BarPoint[]
  ranges?: { value: number; label: string }[]
  defaultRange?: number
  unit?: string
  loading?: boolean
  className?: string
}

const defaultRanges = [
  { value: 3, label: "Últimos 3 meses" },
  { value: 7, label: "Últimos 7 meses" },
]

export function BarTrendCard({ title = "Expedientes cerrados", data, ranges = defaultRanges, defaultRange = 7, unit = "expedientes", loading = false, className }: BarTrendCardProps) {
  const reduce = !!useReducedMotion()
  const selectId = useId()
  const [range, setRange] = useState(defaultRange)
  const shown = data.slice(-range)
  const max = Math.max(1, ...shown.map((point) => point.value))
  return (
    <AeCard
      title={title}
      className={className}
      action={
        <>
          <label htmlFor={selectId} className="sr-only">
            Periodo
          </label>
          <select id={selectId} value={range} onChange={(event) => setRange(Number(event.target.value))} className="h-9 rounded-full border border-input bg-background px-3 text-xs font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring">
            {ranges.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </>
      }
    >
      {loading ? (
        <AeSkeleton rows={4} />
      ) : shown.length === 0 ? (
        <AeEmpty>Sin datos en este periodo.</AeEmpty>
      ) : (
        <figure className="grid gap-2">
          <figcaption className="sr-only">
            {title}: {shown.map((point) => `${point.label} ${point.value} ${unit}`).join(", ")}
          </figcaption>
          <div className="flex h-48 items-end gap-2 sm:gap-3" aria-hidden>
            {shown.map((point, index) => {
              const last = index === shown.length - 1
              return (
                <div key={`${range}-${point.label}`} className="flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-2">
                  <span className={cn("text-xs font-semibold tabular-nums", last ? "text-primary" : "text-muted-foreground")}>{point.value}</span>
                  <motion.div
                    className={cn("w-full max-w-12 rounded-full", last ? "bg-primary shadow-md" : "bg-muted")}
                    style={{ height: `${(point.value / max) * 100}%`, originY: 1 }}
                    initial={{ scaleY: reduce ? 1 : 0 }}
                    animate={{ scaleY: 1 }}
                    transition={growTransition(reduce, index)}
                  />
                  <span className="text-xs text-muted-foreground">{point.label}</span>
                </div>
              )
            })}
          </div>
        </figure>
      )}
    </AeCard>
  )
}

"use client"

/** Clean-room AE dashboard piece. A horizontal day picker with the next appointment in a dark nested card. Theme tokens only. */

import { useRef, useState, type KeyboardEvent } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Clock, MapPin } from "lucide-react"

import { cn } from "@/lib/utils"
import { avatarContrast } from "@/lib/ae-dash"
import { AvatarGroup } from "@/components/ui/avatar-group"
import { AeCard, AeEmpty } from "@/components/ui/ae/card-shell"

export type ScheduleDay = { id: string; weekday: string; day: number }
export type ScheduleItem = { id: string; day: string; time: string; title: string; client: string; people: string[]; place: string }

export type DayScrollerScheduleProps = {
  title?: string
  days: ScheduleDay[]
  items: ScheduleItem[]
  defaultDay?: string
  onSelectDay?: (day: string) => void
  className?: string
}

export function DayScrollerSchedule({ title = "Agenda de citas", days, items, defaultDay, onSelectDay, className }: DayScrollerScheduleProps) {
  const reduce = !!useReducedMotion()
  const [selected, setSelected] = useState(defaultDay ?? days[0]?.id ?? "")
  const focusable = days.some((day) => day.id === selected) ? selected : days[0]?.id
  const refs = useRef<(HTMLButtonElement | null)[]>([])
  const dayItems = items.filter((item) => item.day === selected).sort((a, b) => a.time.localeCompare(b.time))
  const [next, ...rest] = dayItems
  const pick = (id: string) => {
    setSelected(id)
    onSelectDay?.(id)
  }
  const onKeyDown = (event: KeyboardEvent, index: number) => {
    const to = ({ ArrowRight: index + 1, ArrowLeft: index - 1, Home: 0, End: days.length - 1 } as Record<string, number>)[event.key]
    if (to === undefined) return
    event.preventDefault()
    const clamped = Math.max(0, Math.min(days.length - 1, to))
    pick(days[clamped].id)
    refs.current[clamped]?.focus()
  }
  return (
    <AeCard title={title} className={className}>
      <div role="tablist" aria-label="Días" className="-mx-1 flex snap-x gap-2 overflow-x-auto px-1 pb-1 [scrollbar-width:none]">
        {days.map((day, index) => {
          const active = day.id === selected
          const count = items.filter((item) => item.day === day.id).length
          return (
            <button
              key={day.id}
              ref={(node) => {
                refs.current[index] = node
              }}
              role="tab"
              type="button"
              aria-selected={active}
              tabIndex={day.id === focusable ? 0 : -1}
              aria-label={`${day.weekday} ${day.day}, ${count} ${count === 1 ? "cita" : "citas"}`}
              onClick={() => pick(day.id)}
              onKeyDown={(event) => onKeyDown(event, index)}
              className={cn(
                "relative flex w-14 shrink-0 snap-start flex-col items-center gap-1 rounded-full px-2 py-3 text-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                active ? "bg-primary text-primary-foreground shadow-md" : "bg-muted/60 text-muted-foreground hover:bg-muted hover:text-foreground",
              )}
            >
              <span className="text-xs">{day.weekday}</span>
              <span className="text-lg font-bold tabular-nums">{day.day}</span>
              <span aria-hidden className={cn("size-1 rounded-full", count ? (active ? "bg-primary-foreground" : "bg-primary") : "bg-transparent")} />
            </button>
          )
        })}
      </div>
      <div role="tabpanel" aria-label="Citas del día" className="grid gap-3">
        <AnimatePresence mode="wait" initial={false}>
          <motion.div key={selected} initial={reduce ? { opacity: 0 } : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: reduce ? 0 : 0.22 }} className="grid gap-3">
            {!next ? (
              <AeEmpty>No hay citas este día.</AeEmpty>
            ) : (
              <>
                <article aria-label={`Próxima cita: ${next.title}`} className="grid gap-3 rounded-3xl bg-foreground p-5 text-background shadow-lg">
                  <p className="text-xs font-medium tracking-wide uppercase opacity-70">Próxima cita</p>
                  <h4 className="text-lg leading-tight font-semibold">{next.title}</h4>
                  <p className="text-sm opacity-80">con {next.client}</p>
                  <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs opacity-80">
                    <span className="inline-flex items-center gap-1">
                      <Clock aria-hidden className="size-3.5" />
                      {next.time}
                    </span>
                    <span className="inline-flex items-center gap-1">
                      <MapPin aria-hidden className="size-3.5" />
                      {next.place}
                    </span>
                  </div>
                  <AvatarGroup members={next.people.map((name) => ({ name }))} max={4} size="sm" classNames={avatarContrast} label="Participantes" />
                </article>
                {rest.map((item) => (
                  <div key={item.id} className="flex min-w-0 items-center gap-3 rounded-2xl bg-muted/60 px-4 py-3 text-sm">
                    <span className="font-semibold tabular-nums">{item.time}</span>
                    <span className="min-w-0 flex-1 truncate">{item.title} · {item.client}</span>
                  </div>
                ))}
              </>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
    </AeCard>
  )
}

